def ordered(text, edits):
    result = sorted(edits, key=lambda e: e['start'])
    previous = None
    for edit in result:
        start, end = edit['start'], edit['end']
        if not isinstance(start,int) or not isinstance(end,int) or not 0 <= start <= end <= len(text):
            raise ValueError('bad edit')
        if previous is not None and (start < previous['end'] or start == previous['start']):
            raise ValueError('overlapping edits')
        previous = edit
    return result

